from playwright.sync_api import sync_playwright
U='http://localhost:8765/'
with sync_playwright() as p:
    b=p.chromium.launch();E=[]
    c=b.new_context(bypass_csp=True,viewport={'width':1280,'height':860},accept_downloads=True);pg=c.new_page()
    pg.on('pageerror',lambda e:E.append('pageerror '+str(e)));pg.on('console',lambda m:m.type=='error' and E.append('console '+m.text))
    pg.goto(U);pg.wait_for_selector('#stats div');pg.wait_for_timeout(300)
    print('stats',pg.inner_text('#stats').replace('\n',' '));print('week',pg.inner_text('#weekNote')[:120],pg.locator('#week .card').count())
    pg.screenshot(path='screenshots/v2-step1-home.png',full_page=True)
    pg.click('[data-t=find]');print(pg.inner_text('#count'))
    pg.select_option('#fInd','Finance & Accounting');pg.select_option('#fState','NC');print('fin NC',pg.inner_text('#count'))
    pg.on('dialog',lambda d:d.accept('NC finance'));pg.click('#saveF');print('saved',pg.inner_text('#savedList'))
    pg.select_option('#fInd','');pg.select_option('#fState','');pg.check('#fRemote');print('remote',pg.inner_text('#count'))
    pg.uncheck('#fRemote');pg.select_option('#fWin','month');print('month',pg.inner_text('#count'))
    pg.select_option('#fWin','');pg.select_option('#fYear','Sophomore');print('soph',pg.inner_text('#count'))
    pg.select_option('#fYear','');pg.select_option('#fType','Co-op');print('coop',pg.inner_text('#count'))
    pg.click('.sf .pill >> nth=0');print('applied',pg.input_value('#fInd'),pg.input_value('#fState'),pg.inner_text('#count'))
    pg.screenshot(path='screenshots/v2-step1-find.png')
    pg.click('[data-t=profile]');pg.fill('[name=school]','Test U');pg.select_option('[name=classYear]','Junior');pg.check('#pInd [value="Finance & Accounting"]');pg.click('#profForm button');print('prof',pg.evaluate("localStorage.idr_profile"))
    pg.click('[data-t=add]');pg.fill('#addForm [name=company]','Test Co');pg.fill('#addForm [name=title]','Test Intern');pg.fill('#addForm [name=location]','Charlotte, NC');pg.fill('#addForm [name=apply_url]','https://example.com/x');pg.click('button[form=addForm]');pg.wait_for_timeout(200)
    print('add',pg.inner_text('#addMsg'),pg.locator('#mine .card').count(),pg.evaluate("JSON.parse(localStorage.idr_reviewQueue).length"))
    with pg.expect_download() as d: pg.click('#exp')
    d.value.save_as('/tmp/export.json');print('export ok',open('/tmp/export.json').read()[:80].replace('\n',''))
    a=c.new_page();a.on('pageerror',lambda e:E.append('admin '+str(e)))
    a.goto(U+'admin.html');a.fill('#pw','wrong');a.click('#gForm button');a.wait_for_timeout(200);print('gate',a.inner_text('#gMsg'))
    a.fill('#pw',open('/tmp/admin_pw.txt').read().strip());a.click('#gForm button');a.wait_for_selector('#aList table');print('admin',a.inner_text('#aStats').replace('\n',' '))
    a.click('.qi button >> nth=0');a.wait_for_timeout(200);print('queue after',a.inner_text('#queue')[:40])
    a.set_input_files('#csv','/tmp/t.csv');a.wait_for_timeout(300);print('csv',a.inner_text('#csvOut'));a.click('#csvGo')
    a.fill('#aq','Acme Test');a.wait_for_timeout(100);a.click('#aList button >> nth=0');a.fill('#eForm [name=notes]','edited');a.click('#eForm button');print('edited',a.inner_text('#aList')[:200].replace('\n',' '))
    a.fill('#aq','');a.screenshot(path='screenshots/v2-step1-admin.png')
    with a.expect_download() as d: a.click('#exportData')
    import json;j=json.load(open(d.value.path()));print('export data.json',j['count'],j['internships'][0]['company'])
    # import into fresh context
    c2=b.new_context(bypass_csp=True);p2=c2.new_page();p2.goto(U);p2.wait_for_selector('#stats div');p2.set_input_files('#imp','/tmp/export.json')
    p2.on('dialog',lambda d:d.accept());p2.wait_for_timeout(800);print('imported profile',p2.evaluate("localStorage.idr_profile")[:60])
    m=b.new_page(bypass_csp=True,viewport={'width':390,'height':844},device_scale_factor=2,is_mobile=True);m.on('pageerror',lambda e:E.append('mobile '+str(e)))
    m.goto(U);m.wait_for_selector('#stats div');m.screenshot(path='screenshots/v2-step1-mobile.png',full_page=False)
    m.click('[data-t=find]');m.wait_for_selector('#list .card');print('mobile overflow',m.evaluate('document.documentElement.scrollWidth'))
    print('ERRORS',E)
